"""Generate a standalone authoring review. This is not a playable game or Unity render."""
from pathlib import Path
import json
import argparse
HTML='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PLUGIN 흐름·난관 배치 검토</title>
<style>*{box-sizing:border-box}body{margin:0;background:#09131d;color:#d5e7ef;font:15px system-ui}header,main{max-width:1280px;margin:auto;padding:24px}h1{font-size:25px}p{line-height:1.7}nav{display:flex;gap:12px;flex-wrap:wrap}button,select{font:inherit;background:#183246;color:#d5e7ef;padding:9px;border:1px solid #38627c;border-radius:5px}svg{width:100%;background:#0e2030;min-height:260px;margin-top:20px;border:1px solid #264d61}article{background:#112838;padding:22px;border-radius:6px;margin-top:20px}small{color:#8facbf}.rhythm{display:flex;height:24px;margin:6px 0 20px}.flow{background:#2d9fba}.challenge{background:#d88b43}.rest{background:#739785}li{margin:9px 0;line-height:1.7}</style>
<header><h1>다섯 층의 흐름과 난관</h1><p>필수 이동: 흐름 75% · 난관 25% / 구간당 필수 난관 1개</p><small>실제 코드·데이터를 이용한 배치 검토입니다. Unity 게임 실행 화면·성공률·플레이 시간 측정 결과가 아닙니다.</small></header>
<main><nav><select id="floor" aria-label="층 선택"></select><select id="room" aria-label="방 선택"></select><select id="tier" aria-label="시험 방 난도"><option value="Easy">쉬움</option><option value="Normal" selected>보통</option><option value="Hard">어려움·선택</option></select><button id="safe">안전 흐름 방</button></nav><svg id="map" role="img" aria-label="타일 좌표 배치"></svg><p><small>A 고정 · a 일회용 · M 이동 · C 재시도 · E 출구 / 파랑 흐름 · 주황 난관 · 녹색 호흡</small></p><article id="detail"></article><article><h2>선택한 층의 다섯 구간</h2><div id="rhythm"></div><small id="rhythmSummary"></small></article></main>
<script>const data=__DATA__,floorSelect=document.querySelector('#floor'),select=document.querySelector('#room'),tier=document.querySelector('#tier'),map=document.querySelector('#map'),detail=document.querySelector('#detail');let safe=false;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
for(const f of data.floors){const o=document.createElement('option');o.value=f.id;o.textContent=f.name;floorSelect.append(o)}
function loadFloor(){select.replaceChildren();for(const r of data.rooms.filter(r=>r.floor===Number(floorSelect.value))){const o=document.createElement('option');o.value=r.id;o.textContent=r.id+' '+r.title;select.append(o)}safe=false;tier.value='Normal';show()}
function show(){const design=data.rooms.find(r=>r.id===select.value),live=design.prototype;tier.disabled=!live;document.querySelector('#safe').disabled=!live;if(!live)safe=false;
const r=live?data.prototypes.find(p=>p.floor===Number(floorSelect.value)&&p.tier===tier.value&&p.precision===!safe):design,w=r.width,h=r.height;map.setAttribute('viewBox','-1 -1 '+(w+2)+' '+(h+2));
let svg='<defs><pattern id="grid" width="1" height="1" patternUnits="userSpaceOnUse"><path d="M1 0H0V1" fill="none" stroke="#274052" stroke-width=".02"/></pattern></defs><rect width="'+w+'" height="'+h+'" fill="url(#grid)"/><rect width="'+w+'" height=".5" fill="#46738a"/>';
for(const [a,b,y,t] of r.blocks)svg+='<rect x="'+a+'" y="'+(14-t)+'" width="'+(b-a+1)+'" height="'+Math.max(1,t-y+1)+'" fill="#32596b"/>';
for(const [a,b,y] of r.hazards)svg+='<rect x="'+a+'" y="'+(14-y-.9)+'" width="'+(b-a+1)+'" height=".9" fill="#d96543"/>';
for(const g of (r.gimmicks||[])){if(g.kind==='scan')svg+='<rect x="'+(g.x-g.width*.5)+'" y="6" width="'+g.width+'" height="8" fill="#f3d45244"/>';if(g.kind==='gate')svg+='<rect x="'+(g.x-.375)+'" y="6" width=".75" height="8" fill="#e79550aa"/>';if(g.kind==='vent')svg+='<rect x="'+(g.x-1.5)+'" y="3" width="3" height="9.4" fill="#55bdf344"/>';if(g.kind==='timed')svg+='<circle cx="'+g.x+'" cy="'+(14-g.y)+'" r=".65" fill="none" stroke="#edb566" stroke-width=".08" stroke-dasharray=".14 .1"/>';}
for(const [x,y,c] of r.points){const color=c==='M'?'#68e2ad':c==='a'?'#ffc66a':c==='A'?'#67d3ff':'#e0eaf1';svg+='<circle cx="'+x+'" cy="'+(14-y)+'" r=".38" fill="none" stroke="'+color+'" stroke-width=".08"/><text x="'+x+'" y="'+(14-y-.6)+'" fill="'+color+'" font-size=".8" text-anchor="middle">'+escape(c)+'</text>';if(c==='M'&&live&&r.verticalMotion)svg+='<path d="M'+x+' '+(14-y-r.amplitude)+'V'+(14-y+r.amplitude)+'" stroke="#68e2ad" stroke-width=".06"/>';else if(c==='M'&&live)svg+='<path d="M'+(x-r.amplitude)+' '+(14-y)+'H'+(x+r.amplitude)+'" stroke="#68e2ad" stroke-width=".06"/>';}
map.innerHTML=svg;detail.innerHTML='<small>'+(live?'시험 씬의 실제 데이터 / '+tier.options[tier.selectedIndex].text+' / '+(safe?'안전 바닥':'위험 구간'):'설계안 / 관련 기믹 구현 대기')+'</small><h2>'+escape(design.title)+'</h2><p>'+escape(design.purpose)+'</p><ol>'+design.solutions.map(s=>'<li>'+escape(s)+'</li>').join('')+'</ol><p>실패: '+escape(design.penalty)+'</p><p>보상: '+escape(design.reward)+'</p><p><small>'+escape(design.dependency.join(' / '))+'</small></p>';const f=data.floors[Number(floorSelect.value)];document.querySelector('#rhythm').innerHTML=f.stages.map(s=>'<div>'+escape(s.name)+' / '+s.flow+' + '+s.challenge+' + '+s.rest+'타일</div><div class="rhythm"><span class="flow" style="flex:'+s.flow+'"></span><span class="challenge" style="flex:'+s.challenge+'"></span><span class="rest" style="flex:'+s.rest+'"></span></div>').join('');document.querySelector('#rhythmSummary').textContent=f.hint+' 흐름75%·난관25%의 설계안이며, 기존 Main 전체 맵을 교체한 것은 아닙니다.';}
select.onchange=()=>{safe=false;if(select.value.endsWith('02'))tier.value='Hard';show()};tier.onchange=show;document.querySelector('#safe').onclick=()=>{safe=!safe;show()};
floorSelect.onchange=loadFloor;loadFloor();</script></html>'''
def main():
    p=argparse.ArgumentParser();p.add_argument('export',type=Path);args=p.parse_args();root=Path(__file__).resolve().parents[1]
    source=json.loads(args.export.read_text());source['rooms']=json.loads((root/'Design/TraversalDesigns.json').read_text());
    for r in source['rooms']:r['floor']=0
    source['rooms']+=json.loads((root/'Design/FloorTraversalDesigns.json').read_text())['rooms']
    for r in source['rooms']:r['prototype']=r['id'].endswith(('01','02'))
    assert len(source['rooms'])==60 and len(source['prototypes'])==30
    payload=json.dumps(source,ensure_ascii=False).replace('<','\\u003c');(root/'TraversalPreview.html').write_text(HTML.replace('__DATA__',payload))
    print('PASS:60 designs and30 actual floor/room/profile combinations exported into TraversalPreview.html')
if __name__=='__main__':main()
